INSERT INTO creatures (id, title, source, subgroup, summary, meta, portrait, tags, creature_stats, callouts, sort_order) VALUES
('c5', 'Имперский крестьянин', 'gm', 'Великое герцогство Талабек', 'Обычный житель деревни привык защищать свой дом и семью. В одиночку он не представляет серьёзной угрозы для опытного бойца, но в составе разъярённой толпы, вооружённой факелами и вилами, способен задавить противника числом и напором.', 'Угроза: низкая', 'https://cdn.poehali.dev/projects/8ea67526-cf7e-472d-ad6c-bad53fcea4bc/bucket/30d3631b-3761-4323-bde8-c94fc63c3078.png', '["крестьянин", "талабек", "империя", "прислужник"]'::jsonb, '{"characteristics": [{"code": "ББ", "value": 2}, {"code": "ДБ", "value": 3}, {"code": "С", "value": 3}, {"code": "В", "value": 3}, {"code": "И", "value": 2}, {"code": "Пр", "value": 3}, {"code": "Р", "value": 2}, {"code": "Х", "value": 2}], "speed": "Нормальная", "wounds": 3, "type": "Прислужник", "skills": ["обычные 2", "тяжёлый труд 3"], "attacks": [{"name": "Импровизированное оружие", "range": "Ближняя", "formula": "2d/2", "damage": "2", "rounds": "1Р"}, {"name": "Охотничий лук", "range": "Средняя-дальняя", "formula": "3d/2", "damage": "3", "rounds": "2Р"}], "defenses": ["Атлетика 3d/2"], "abilities": [{"name": "Факелы и вилы", "description": "Толпа разъярённых крестьян может одолеть врага за счёт численного преимущества. Когда крестьянин помогает союзнику совершить проверку рукопашного боя, проверка не требуется — цель получает модификатор +1d к проверке рукопашного боя. Этот модификатор может превышать обычный максимальный предел дополнительных костей.", "descriptionLinks": [{"match": "рукопашного боя", "entryId": "skill-melee"}], "linkEntryId": "r5"}], "equipment": [{"name": "Боевой лук", "linkEntryId": "i36"}, {"name": "Сельский наряд", "linkEntryId": "i51"}, {"name": "Фермерские инструменты", "linkEntryId": "i17"}]}'::jsonb, NULL, 0),
('c6', 'Имперский горожанин', 'gm', 'Великое герцогство Талабек', 'Горожане — основа хозяйственной жизни любого торгового и производственного центра. Они трудятся как на частных нанимателей, так и на городскую администрацию. Среди них можно встретить самых разных специалистов: банкиров и писарей, лоточников и трактирщиков, продавцов газет, конюхов, лавочников, мытарей и прачек. Все они — типичные представители городского населения, обеспечивающие повседневную работу города.', 'Угроза: низкая', 'https://cdn.poehali.dev/projects/8ea67526-cf7e-472d-ad6c-bad53fcea4bc/bucket/d1e57464-15b4-4a65-acb8-7ea632ef02b3.png', '["горожанин", "талабек", "империя", "прислужник"]'::jsonb, '{"characteristics": [{"code": "ББ", "value": 2}, {"code": "ДБ", "value": 2}, {"code": "С", "value": 3}, {"code": "В", "value": 3}, {"code": "И", "value": 3}, {"code": "Пр", "value": 3}, {"code": "Р", "value": 3}, {"code": "Х", "value": 3}], "speed": "Нормальная", "wounds": 3, "type": "Прислужник", "skills": ["обаяние 3", "обычные 2", "память 3", "сила воли 3"], "attacks": [{"name": "Кинжал", "range": "Ближняя", "formula": "2d/2", "damage": "2", "rounds": "1Р"}], "defenses": ["Атлетика 3d/2"], "abilities": [{"name": "Уличная смекалка", "description": "Завсегдатаи города знают, что нужно настороженно следить за ловкими воришками. Горожане получают модификатор +1d к встречным проверкам наблюдательности, когда противостоят попыткам их обворовать.", "descriptionLinks": [{"match": "встречным проверкам", "entryId": "r8"}, {"match": "наблюдательности", "entryId": "skill-observation"}]}], "equipment": [{"name": "Бюргерский наряд", "linkEntryId": "i7"}, {"name": "Кинжал", "linkEntryId": "i6"}, {"name": "Мелочь (серебро)"}, {"name": "Ремесленные инструменты по профессии (если уместно)", "linkEntryId": "i8"}]}'::jsonb, NULL, 1),
('c7', 'Ремесленник', 'gm', 'Великое герцогство Талабек', 'Ремесленники обеспечивают Империю самыми разными товарами: от простых вещей первой необходимости, таких как хлеб и свечи, до уникальных изделий — дорогого оружия и даже боевых кораблей. В крупных и средних городах ремесленники объединены в гильдии. Их главная задача — защищать интересы гильдмейстеров и не допускать недобросовестной конкуренции. Без такой защиты рядовой ремесленник быстро разорится, если рынок наводнит дешёвая и низкокачественная продукция. Гильдии жёстко следят за соблюдением стандартов качества: нарушителя исключают из объединения, после чего он лишается возможности заниматься своим ремеслом не только в городе, но и в ближайших окрестностях.', 'Угроза: низкая', 'https://cdn.poehali.dev/projects/8ea67526-cf7e-472d-ad6c-bad53fcea4bc/bucket/051867d0-1afd-43d5-90bc-d8952b864bbf.png', '["ремесленник", "гильдия", "талабек", "империя", "прислужник"]'::jsonb, '{"characteristics": [{"code": "ББ", "value": 2}, {"code": "ДБ", "value": 2}, {"code": "С", "value": 3}, {"code": "В", "value": 3}, {"code": "И", "value": 3}, {"code": "Пр", "value": 3}, {"code": "Р", "value": 3}, {"code": "Х", "value": 2}], "speed": "Нормальная", "wounds": 3, "type": "Прислужник", "skills": ["обычные 2", "сила воли 3", "сноровка 4", "тяжёлый труд 4"], "attacks": [{"name": "Импровизированное оружие", "range": "Ближняя", "formula": "2d/2", "damage": "2", "rounds": "1Р"}], "defenses": ["Атлетика 3d/2"], "abilities": [{"name": "Профессиональная гордость", "description": "Ни один уважающий себя ремесленник не станет производить работу низкого качества, но небольшая дополнительная плата может дать дополнительные преимущества. Если персонаж платит дополнительную монету при получении любого имущества напрямую от ремесленника (создателя), следующая проверка, связанная с использованием этого имущества, получает модификатор +1d."}], "equipment": [{"name": "Мелочь (медь)"}, {"name": "Рабочая кожаная одежда", "linkEntryId": "i9"}, {"name": "Ремесленные инструменты по профессии", "linkEntryId": "i8"}]}'::jsonb, NULL, 2),
('c8', 'Городской стражник', 'gm', 'Великое герцогство Талабек', 'Представитель городской стражи охраняет улицы и следит за порядком. Он обучен звать подкрепление, если сталкивается с угрозой, которая ему не по силам, поэтому нападение на одного стражника быстро может обернуться стычкой с целым отрядом.', 'Угроза: низкая', 'https://cdn.poehali.dev/projects/8ea67526-cf7e-472d-ad6c-bad53fcea4bc/bucket/de873254-e36b-4f6e-9c59-acf5a943907f.webp', '["стража"]'::jsonb, '{"characteristics": [{"code": "ББ", "value": 3}, {"code": "ДБ", "value": 3}, {"code": "С", "value": 3}, {"code": "В", "value": 3}, {"code": "И", "value": 3}, {"code": "Пр", "value": 3}, {"code": "Р", "value": 3}, {"code": "Х", "value": 3}], "speed": "Нормальная", "wounds": "4 (бронированный)", "type": "Прислужник", "skills": ["атлетика 3", "лидерство 3", "мощь 3", "наблюдательность 3", "обычные 2", "рукопашный бой 3"], "attacks": [{"name": "Древковое оружие", "range": "Ближняя", "formula": "3d/3", "damage": "5", "rounds": "2Р"}], "defenses": ["Атлетика 3d/3"], "abilities": [{"name": "Осведомитель", "description": "Городская стража обучена вызывать подкрепление, когда сталкивается с проблемой, с которой не может справиться.\n\nОни могут подать сигнал о помощи в рамках действия восстановление — если они это сделают, на следующем ходу обязательно прибудет больше стражников, а любые проверки атлетики для отступления от них считаются мрачными."}], "equipment": [{"name": "Алебарда", "linkEntryId": "i15"}, {"name": "Лёгкая броня", "linkEntryId": "i1"}, {"name": "Мундир", "linkEntryId": "i14"}, {"name": "Набор для освещения", "linkEntryId": "i67"}, {"name": "Собранные взятки (медь)"}]}'::jsonb, NULL, 3),
('c9', 'Грабитель', 'gm', 'Великое герцогство Талабек', 'Ловкий преступник промышляет кражами и грабежами в тени городских переулков. Он действует скрытно, наносит удар из засады и предпочитает исчезнуть до того, как жертва успеет позвать на помощь.', 'Угроза: низкая', 'https://cdn.poehali.dev/projects/8ea67526-cf7e-472d-ad6c-bad53fcea4bc/bucket/fcc0e0d9-353e-415d-87cf-6546bdb50317.webp', '["преступник"]'::jsonb, '{"characteristics": [{"code": "ББ", "value": 3}, {"code": "ДБ", "value": 2}, {"code": "С", "value": 3}, {"code": "В", "value": 3}, {"code": "И", "value": 3}, {"code": "Пр", "value": 3}, {"code": "Р", "value": 2}, {"code": "Х", "value": 2}], "speed": "Нормальная", "wounds": 3, "type": "Прислужник", "skills": ["атлетика 3", "лидерство 3", "обычные 2", "рукопашный бой 3", "скрытность 3"], "attacks": [{"name": "Кинжал", "range": "Ближняя", "formula": "3d/3", "damage": "2", "rounds": "1Р"}], "defenses": ["Атлетика 3d/3"], "abilities": [{"name": "Затаившийся", "description": "Грабители крадутся в тенях, прежде чем нанести удар, а после дела бесследно исчезают. Вне боя проверки наблюдательности, чтобы заметить затаившегося грабителя, считаются мрачными.", "descriptionLinks": [{"match": "наблюдательности", "entryId": "skill-observation"}, {"match": "мрачными", "entryId": "r3"}]}], "equipment": [{"name": "Воровские инструменты", "linkEntryId": "i71"}, {"name": "Кинжал", "linkEntryId": "i6"}, {"name": "Одежда для маскировки", "linkEntryId": "i53"}]}'::jsonb, NULL, 4),
('c10', 'Разбойник', 'gm', 'Великое герцогство Талабек', 'Разбойник с большой дороги промышляет грабежом одиноких путников и небольших караванов. В одиночку он не так опасен, но разбойники редко действуют поодиночке: трусливая по своей природе банда становится куда смелее и опаснее, стоит ей ощутить численный перевес.', 'Угроза: низкая', 'https://cdn.poehali.dev/projects/8ea67526-cf7e-472d-ad6c-bad53fcea4bc/bucket/51bc4e67-a392-4be6-8d75-37ccdc10ef92.webp', '["разбойник"]'::jsonb, '{"characteristics": [{"code": "ББ", "value": 3}, {"code": "ДБ", "value": 3}, {"code": "С", "value": 3}, {"code": "В", "value": 3}, {"code": "И", "value": 3}, {"code": "Пр", "value": 3}, {"code": "Р", "value": 2}, {"code": "Х", "value": 2}], "speed": "Нормальная", "wounds": "4 (бронированный)", "type": "Прислужник", "skills": ["лидерство 3", "обычные 2", "рукопашный бой 3", "скрытность 3", "стрельба 3"], "attacks": [{"name": "Боевой лук", "range": "Средняя-дальняя", "formula": "3d/3", "damage": "3", "rounds": "2Р"}, {"name": "Топор", "range": "Ближняя", "formula": "3d/3", "damage": "3", "rounds": "1Р"}], "defenses": ["Атлетика 3d/3"], "abilities": [{"name": "Стая трусов", "description": "Поодиночке разбойники трусливы, но осмелевают, чувствуя численное превосходство. Пока в зоне разбойника находится хотя бы один союзник, он получает модификатор +1d к проверкам сила воли."}], "equipment": [{"name": "Мелочь (серебро)"}, {"name": "Одежда для маскировки", "linkEntryId": "i53"}, {"name": "Топор", "linkEntryId": "i23"}]}'::jsonb, NULL, 5),
('c11', 'Наёмный головорез', 'gm', 'Великое герцогство Талабек', 'Головорез продаёт свои услуги тому, кто больше заплатит: будь то запугивание должника или устранение неугодного свидетеля. Он не гнушается грязной работой и действует жёстко и без колебаний.', 'Угроза: низкая', 'https://cdn.poehali.dev/projects/8ea67526-cf7e-472d-ad6c-bad53fcea4bc/bucket/61f1f70a-df51-4c31-9d61-1a0e93267c9a.webp', '["наёмник"]'::jsonb, '{"characteristics": [{"code": "ББ", "value": 3}, {"code": "ДБ", "value": 3}, {"code": "С", "value": 3}, {"code": "В", "value": 3}, {"code": "И", "value": 3}, {"code": "Пр", "value": 3}, {"code": "Р", "value": 2}, {"code": "Х", "value": 2}], "speed": "Нормальная", "wounds": "4 (бронированный)", "type": "Прислужник", "skills": ["атлетика 3", "мощь 3", "обычные 2", "рукопашный бой 3"], "attacks": [{"name": "Дубина", "range": "Ближняя", "formula": "3d/3", "damage": "3", "rounds": "1Р"}], "defenses": ["Атлетика 3d/3"], "abilities": [{"name": "Запугивание", "description": "Головорезы умело внушают страх, чтобы добиться нужного результата без лишнего насилия. Они получают модификатор +1d к проверкам устрашения против персонажей, которые слабее их физически."}], "equipment": [{"name": "Дубина", "linkEntryId": "i24"}, {"name": "Задаток за работу (серебро)"}, {"name": "Лёгкая броня", "linkEntryId": "i1"}]}'::jsonb, NULL, 6),
('c12', 'Контрабандист', 'gm', 'Великое герцогство Талабек', 'Контрабандист зарабатывает на перевозке запрещённых или неучтённых товаров, избегая внимания таможни и стражи. Он хорошо знает тайные тропы и умеет договариваться — а если не выходит договориться, готов постоять за себя.', 'Угроза: низкая', 'https://cdn.poehali.dev/projects/8ea67526-cf7e-472d-ad6c-bad53fcea4bc/bucket/7e6db2f4-1e5c-4326-8f1a-b2e57c9b6f21.webp', '["контрабандист"]'::jsonb, '{"characteristics": [{"code": "ББ", "value": 3}, {"code": "ДБ", "value": 3}, {"code": "С", "value": 3}, {"code": "В", "value": 3}, {"code": "И", "value": 3}, {"code": "Пр", "value": 3}, {"code": "Р", "value": 2}, {"code": "Х", "value": 3}], "speed": "Нормальная", "wounds": 3, "type": "Прислужник", "skills": ["обаяние 3", "обычные 2", "рукопашный бой 3", "скрытность 3"], "attacks": [{"name": "Кинжал", "range": "Ближняя", "formula": "3d/3", "damage": "2", "rounds": "1Р"}], "defenses": ["Атлетика 3d/3"], "abilities": [{"name": "Знание тайных троп", "description": "Контрабандисты хорошо знают неприметные пути в обход застав и патрулей. Они игнорируют штрафы, связанные с пересечённой местностью, при попытке скрытно провезти груз."}], "equipment": [{"name": "Кинжал", "linkEntryId": "i6"}, {"name": "Контрабандный товар (серебро)"}, {"name": "Одежда для маскировки", "linkEntryId": "i53"}]}'::jsonb, NULL, 7)
